function gridContains(grid: number[][], target: number): boolean {
  // find the last row whose first value is <= target
  let lo = 0, hi = grid.length - 1, row = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (grid[mid][0] <= target) { row = mid; lo = mid + 1; }
    else hi = mid - 1;
  }
  if (row === -1) return false; // target is smaller than everything
  const r = grid[row];
  lo = 0; hi = r.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (r[mid] === target) return true;
    if (r[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return false;
}

