function gridContains(grid: number[][], target: number): boolean {
  const cols = grid[0].length;
  let lo = 0, hi = grid.length * cols - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const v = grid[Math.floor(mid / cols)][mid % cols];
    if (v === target) return true;
    if (v < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return false;
}

